package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class Node_siblingIndex_TriageGen0Test {

    private Node node;

    @Before
    public void setUp() {
        // Create a simple document with a node to test siblingIndex
        Document doc = Jsoup.parse("<div><p>Test</p><p>Node</p></div>");
        node = doc.body().child(0);
    }

    @Test
    public void testSiblingIndexOfFirstChild() {
        // First child should have sibling index 0
        assertEquals(0, node.siblingIndex());
    }

    @Test
    public void testSiblingIndexOfSecondChild() {
        // Move to second child and check sibling index
        Node secondChild = node.siblingNodes().get(1);
        assertEquals(1, secondChild.siblingIndex());
    }

    @Test
    public void testSiblingIndexOfLastChild() {
        // Move to last child and check sibling index
        Node lastChild = node.siblingNodes().get(node.siblingNodes().size() - 1);
        assertEquals(node.siblingNodes().size() - 1, lastChild.siblingIndex());
    }

    @Test
    public void testSiblingIndexWithSingleNode() {
        // Test with a node that has no siblings
        Node singleNode = new Node();
        assertEquals(-1, singleNode.siblingIndex());
    }

    @Test
    public void testSiblingIndexAfterNodeRemoval() {
        // Remove a node and check sibling indices
        Node removedNode = node.siblingNodes().get(0);
        removedNode.remove();
        Node nextNode = node.siblingNodes().get(0);
        assertEquals(0, nextNode.siblingIndex());
    }

    @Test
    public void testSiblingIndexAfterNodeInsertion() {
        // Insert a node and check sibling indices
        Node newNode = new Node();
        node.before(newNode);
        assertEquals(0, newNode.siblingIndex());
        assertEquals(1, node.siblingIndex());
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testSiblingIndexOutOfBound() {
        // Access a sibling index out of bounds should throw exception
        Node nonExistentNode = node.siblingNodes().get(100);
        nonExistentNode.siblingIndex();
    }
}
